@Override
    public List<OrderItemVO> selectOrderItemPage(Map<String, Object> params, int currentPage, int pageSize) {
        List<OrderItemDO> list = orderItemMapper.selectOrderItemPage(params, (currentPage - 1) * pageSize, pageSize);
        if (CollectionUtils.isEmpty(list)) {
            return null;
        }
        return list.stream().map(this::toOrderItemVO).collect(Collectors.toList());
    }

public List<OrderItemVO> queryOrderItems(String orderNo, String status, int pageNum, int pageSize) {
        Map<String, Object> params = new HashMap<>();
        params.put("orderNo", orderNo);
        params.put("status", status);
        return orderItemInfrastructure.selectOrderItemPage(params, pageNum, pageSize);
    }

protected List<OrderItemVO> queryOrderItems(OrderRouteVO routeVO) {
        if (!RouteCheckStatusEnum.WAIT.getCode().equals(routeVO.getCheckStatus())) {
            return Collections.emptyList();
        }
        return queryOrderItems(routeVO.getOrderNo(), OrderItemStatusEnum.INIT.getCode(), 1, ITEM_PAGE_SIZE);
    }

private void handleOrderItem(OrderRouteVO routeVO, OrderE order) {
        long startTime = System.currentTimeMillis();
        // 循环处理订单明细，每批处理后状态从INIT变为CHECK_ERROR或WAIT_UNDERWRITE，查询结果会越来越少，直到为空退出
        // 兜底限制：最多200次（10万条），超出说明数据异常，打日志告警退出
        int totalItems = 0;
        int maxLoop = 200;
        while (maxLoop-- > 0) {
            List<OrderItemVO> items = queryOrderItems(routeVO);
            if (CollectionUtils.isEmpty(items)) {
                break;
            }
            for (OrderItemVO item : items) {
                handleOrderItem(item, order);
            }
            totalItems += items.size();
            log.info("[明细上传]明细处理中，orderNo：{}，本次处理：{}条，共计：{}条", routeVO.getOrderNo(), items.size(), totalItems);
        }
        long costTime = System.currentTimeMillis() - startTime;
        if (maxLoop < 0) {
            log.error("[明细上传]处理循环达到最大次数，orderNo：{}，耗时：{}ms", routeVO.getOrderNo(), costTime);
            MonitorUtil.monitor(routeVO.getAppCode(),
                    EventEnum.EC_001_18.name(), null, costTime, ErrorEnum.SYS_ERROR.getErrorCode(),
                    String.format("订单明细处理循环达到最大次数，orderNo：%s", routeVO.getOrderNo()));
        } else {
            log.info("[明细上传]明细处理完成，orderNo：{}，耗时：{}ms", routeVO.getOrderNo(), costTime);
        }
    }

public void updateOrderItemStatus(Long itemId, String status) {
        OrderItemVO updateVO = new OrderItemVO();
        updateVO.setId(itemId);
        updateVO.setStatus(status);
        orderItemInfrastructure.updateOrderItemSelective(updateVO);
    }

private OrderItemDO toOrderItemDO(OrderItemVO vo) {
        OrderItemDO orderItemDO = new OrderItemDO();
        BeanUtils.copyProperties(vo, orderItemDO);
        orderItemDO.setValid(ValidUtil.getEffective());
        if (orderItemDO.getGmtCreate() == null) {
            orderItemDO.setGmtCreate(new Date());
        }
        if (orderItemDO.getGmtModified() == null) {
            orderItemDO.setGmtModified(new Date());
        }
        return orderItemDO;
    }

List<OrderItemDO> selectOrderItemPage(@Param("params") Map<String, Object> params,
                                          @Param("offset") Integer offset,
                                          @Param("pageSize") Integer pageSize);

public static void info(String format, Object... args) {
        if (Level.INFO_INT >= logLevel) {
            log.info(format, args);
        }
    }

public AdvertiseResource info(String type, String layout,String title) {
        notBlank(type, "type is required!");

        this.type = type;
        this.layout = layout;
        this.advertiseResourceTitle = title;

        return this;
    }

public AdvertiseResourceItem info(String title, String imageUrl, String link, String linkType) {
        this.title = title;
        this.imageUrl = imageUrl;
        this.link = link;
        this.linkType = linkType;

        return this;
    }
